"""v2 — CH-59: EP-08 Shopping Assistance (new doc) + EP-01, EP-04, PRD-04 index. DEC-330..335, A-37."""
from v2lib import *
SRC = 'پیشنهاد ChatGPT P1'

def p04(s):
    s = front(s, '1.3', 'v2 — CH-59: اپیک EP-08 کمک به خرید و زیرسند PRD-04-EP08؛ FR-13 تا FR-16؛ BR-08')
    s = after_line(s, '| ‏۱۰ | ‏`PRD-04-DD - Data Dictionary.md` |',
        row('۱۱ *(v2)*', '`PRD-04-EP08 - Shopping Assistance.md`', 'پیشنهاد محصول با دلیل، جایگزین، کمک در تردید خرید (Purchase Rescue)، ثبت درخواست‌ها، ویژگی و تصویر، قابلیت‌های دستیار و لحن', '1.0 ✅ (v2)'))
    s = after_line(s, '| ‏EP-07 | ‏کنترل انسانی | ‏BR-07 |',
        row('EP-08 *(v2)*', 'کمک به خرید', 'BR-08 *(v2)*', 'FR-13، FR-14، FR-15، FR-16', 'UCD-20 تا UCD-23 *(v2)*', 'TR-01، TR-03', 'جزء ۷', 'PS-06', 'BO-06', 'الزامی؛ بیرون از هسته محافظت‌شده (DEC-325)', '— (آزمون‌های TS-08 در PRD-11b)'))
    s = after_line(s, '| ‏FR-12 | ‏توقف و مدیریت خطا |',
        '\n'.join([row('FR-13 *(v2)*', 'پیشنهاد محصول با دلیل', 'EP-08', 'EP-01 (فهم)، EP-02 (فیلتر موجودی)', 'EP-08'),
                   row('FR-14 *(v2)*', 'پیشنهاد جایگزین', 'EP-08', 'EP-02 (فقط موجود معتبر)', 'EP-08'),
                   row('FR-15 *(v2)*', 'کمک در تردید خرید (Purchase Rescue)', 'EP-08', 'EP-01، EP-04 (اقدام‌ها)', 'EP-08'),
                   row('FR-16 *(v2)*', 'ثبت درخواست‌ها و نیازهای مشتری', 'EP-08', 'EP-06 (رویداد و گزارش)', 'EP-08، EP-06')]))
    return hist(s, '1.3', 'v2 — CH-59: §4.1 زیرسند ۱۱ (EP-08)، §4.3 ردیف EP-08، §4.4.1 FR-13 تا FR-16 (DEC-321، DEC-330 تا DEC-335)', 'CH-59')

def ep01(s):
    s = front(s, '1.3', 'v2 — CH-59: US-01-03 خروجی فهم (DEC-330)؛ US-01-04 بسط با US-08-01 و US-08-02 (DEC-331، DEC-332)')
    s = after_line(s, '## ‏US-01-03 · رفع ابهام ویژگی‌های محصول',
        '\n> ‏**v2 — CH-59 (DEC-330):** گام فهم علاوه بر محصول و گونه، نیت (VL-15)، موضوع (VL-16)، بودجه، کاربرد، اطلاعات ناقص و مانع خرید (VL-17) را هم برمی‌گرداند؛ جدول کامل در PRD-04-EP08 §8.0. قاعده سؤال تکمیلی و حد نوبت تغییر نکرد.')
    s = after_line(s, '## ‏US-01-04 · یافتن محصول منطبق از کاتالوگ',
        '\n> ‏**v2 — CH-59:** این استوری با **US-08-01** (پیشنهاد با دلیل و فیلتر قیمت، کاربرد و موجودی) و **US-08-02** (جایگزین) بسط یافت. ردیف‌های «موجودی گزینه‌ها» و «ترتیب» و نباید «جایگزین برای محصول ناموجود» جایگزین شدند (DEC-331، DEC-332). وقتی قابلیت «پیشنهاد محصول» خاموش است، همین استوری بی‌تغییر اجرا می‌شود (US-08-06).')
    s = R(s, '| ‏موجودی گزینه‌ها | ‏در فهرست پیشنهادها درباره موجودی چیزی گفته نمی‌شود.',
             '| ‏موجودی گزینه‌ها | ‏*(جایگزین‌شده با DEC-331 (v2) — CH-59: محصولی که همه گونه‌های منطبقش با داده معتبر ناموجودند پیشنهاد نمی‌شود؛ US-08-01)* در فهرست پیشنهادها درباره موجودی چیزی گفته نمی‌شود.')
    s = R(s, '| ‏ترتیب | ‏ترتیب گزینه‌ها ادعای «بهترین»',
             '| ‏ترتیب | ‏*(جایگزین‌شده با DEC-331 (v2) — CH-59: ترتیب قطعی بر امتیاز انطباق؛ US-08-01)* ترتیب گزینه‌ها ادعای «بهترین»')
    s = R(s, '- ‏جایگزین برای محصول ناموجود پیشنهاد نمی‌شود (ND-33؛ مرحله ۲).',
             '- ‏~~جایگزین برای محصول ناموجود پیشنهاد نمی‌شود (ND-33؛ مرحله ۲).~~ *جایگزین‌شده با DEC-332 (v2) — CH-59: US-08-02.*')
    return hist(s, '1.3', 'v2 — CH-59: یادداشت US-01-03 (خروجی فهم)؛ US-01-04 بسط با US-08-01 و US-08-02، دو ردیف و یک نباید جایگزین‌شده (DEC-330 تا DEC-332)', 'CH-59')

def ep04(s):
    s = front(s, '1.3', 'v2 — CH-59: بسته تحویل US-04-02 با «کارهای دستیار» و «اقدام پیشنهادی» (DEC-335)')
    i = s.index('| ‏بسته تحویل | ‏آخرین درخواست مشتری'); j = s.index('\n', i)
    line = s[i:j]
    s = s[:j] + '\n' + row('بسته تحویل — افزوده v2', 'دو بخش تازه در خلاصه: **«کارهای دستیار»** (فهرست کوتاه کارهای ثبت‌شده در رویدادها، مثلاً «موجودی مانتو ب را بررسی کرد: نامشخص»؛ «۳ پیشنهاد جایگزین داد») — از رویدادها ساخته می‌شود نه از مدل؛ و **«اقدام پیشنهادی»** از فهرست ثابت: پاسخ موجودی پس از بررسی · ارسال اطلاعات سیاست · پیشنهاد جایگزین · پیگیری سفارش · بررسی درخواست اقدام · پاسخ پرسش محصول. اقدام پیشنهادی فقط پیشنهاد است و کاری انجام نمی‌دهد', 'DEC-335؛ ' + SRC) + s[j:]
    return hist(s, '1.3', 'v2 — CH-59: US-04-02 ردیف «بسته تحویل — افزوده v2» (DEC-335)', 'CH-59')

DECS = [
 row('DEC-330', '**v2 — خروجی فهم پیام:** نیت (VL-15)، موضوع (VL-16)، موجودیت‌ها (محصول، گونه، سفارش، رنگ، سایز، بودجه، کاربرد، ویژگی‌ها)، اطلاعات ناقص، مانع خرید (VL-17)؛ فهم جدا از نگارش؛ فهم فقط پیشنهاد مسیر است و تصمیم با قاعده (SP-09)', D, 'EP-08 §8.0؛ EP-01 US-01-03؛ ' + SRC, 'CH-59'),
 row('DEC-331', '**v2 — پیشنهاد محصول با دلیل (US-08-01):** فیلتر قطعی ویژگی، قیمت اعلام‌شده، کاربرد و موجودی؛ محصولی که همه گونه‌های منطبقش با داده معتبر ناموجودند پیشنهاد نمی‌شود؛ ترتیب با امتیاز انطباق؛ سقف ۳ (DEC-76)؛ یک خط دلیل از داده. *(جایگزین ردیف‌های «موجودی گزینه‌ها» و «ترتیب» US-01-04)*', D, 'EP-08؛ EP-01؛ ' + SRC, 'CH-59'),
 row('DEC-332', '**v2 — جایگزین (US-08-02):** آغاز با نتیجه معتبر «ناموجود» یا «به کارم نمی‌آید»؛ «نامشخص» و «متعارض» همچنان ارجاع؛ نامزدها: گونه دیگر همان محصول (سایز اجباری هرگز عوض نمی‌شود)، رابطه «جایگزین»، هم‌دسته؛ فقط موجود معتبر؛ امتیاز شباهت ویژگی + نزدیکی قیمت + رابطه؛ سقف ۳ با «تفاوت با انتخاب شما». *(جایگزین نباید «جایگزین برای ناموجود» US-01-04)*', D, 'EP-08؛ EP-01؛ ' + SRC, 'CH-59'),
 row('DEC-333', '**v2 — Purchase Rescue (US-08-03):** واکنشی و درون گفت‌وگو؛ مانع (VL-17) با مدل، اقدام با جدول قطعی مانع ← اقدام از کنش‌های موجود؛ بی تخفیف، بی وعده، بی پیام پیش‌دستانه؛ نتیجه فقط از داده معتبر (VL-21)؛ «خرید انجام شد» گزارش نمی‌شود', D, 'EP-08؛ ' + SRC, 'CH-59'),
 row('DEC-334', '**v2 — ثبت درخواست‌ها (US-08-04):** موضوع، جست‌وجوی بی‌نتیجه، درخواست ناموجود، نیاز پوشش‌داده‌نشده، مانع؛ بی متن پیام؛ پرتکرارها با شمارش (KM-27)؛ تحلیل گروهی در PRD-12', D, 'EP-08؛ EP-06؛ ' + SRC, 'CH-59'),
 row('DEC-335', '**v2 — خلاصه ارجاع:** دو بخش تازه «کارهای دستیار» (از رویدادها) و «اقدام پیشنهادی» (فهرست ثابت) در بسته تحویل', D, 'EP-04 US-04-02؛ PRD-05b؛ ' + SRC, 'CH-59'),
]

def mi(s):
    s = re.sub(r'^version: .*$', 'version: 1.16', s, count=1, flags=re.M)
    s = mi_dec(s, DECS)
    s = after_line(s, '| ‏A-36 *(v2)* |', row('A-37 *(v2)*', 'سرویس مدل در فارسی نیت، موضوع و مانع خرید را با دقت کافی تشخیص می‌دهد', 'CH-59', 'اجرای آزمایشی روز ۴ (PRD-11a)؛ اگر نشد، US-08-03 در ترتیب کاهش اول است'))
    s = after_line(s, '| ‏PRD-04-EP07 - Human Control |', row('PRD-04-EP08 - Shopping Assistance *(v2)*', 'Approved (v2)', '**1.0 (CH-59 v2)**', D, 'v2'))
    s = mi_doc(s, 'PRD-04 - Features (فهرست)', '1.3 (CH-41، CH-44، CH-54، CH-59 v2)', 'v2')
    s = mi_doc(s, 'PRD-04-EP01 - Conversation & Knowledge', '1.3 (CH-31، CH-42، CH-59 v2)', 'v2')
    s = mi_doc(s, 'PRD-04-EP04 - Handoff & Errors', '1.3 (CH-14، CH-42، CH-43، CH-59 v2)', 'v2')
    s = mi_ch(s, row('CH-59', D, '**v2 — پیشنهاد ChatGPT، مورد P1 (اپیک کمک به خرید):** DEC-330 تا DEC-335 و A-37. زیرسند تازه PRD-04-EP08 1.0 با شش استوری US-08-01 تا US-08-06، FR-13 تا FR-16 و جدول نقش مدل و قاعده؛ EP-01 1.3 (یادداشت فهم، بسط US-01-04)؛ EP-04 1.3 (خلاصه ارجاع)؛ PRD-04 1.3. **هنوز همگام نشده:** متن روایی PRD-03 (UCD-20 تا UCD-23)', 'PRD-04، PRD-04-EP08 (تازه)، EP-01، EP-04، Master Index'))
    return s

rw(S + 'PRD-04 - Features.md', p04)
rw(S + 'PRD-04-EP01 - Conversation & Knowledge.md', ep01)
